"""Render the post-review revision from preserved numerical outputs."""
import json
import pandas as pd
from records import ROOT

TITLE='Revisiting reference locations for changes in Swiss declared crop-group diversity: a resampling benchmark'
def read(path):return pd.read_csv(ROOT/path)
def one(frame,**kw):
    for key,value in kw.items():frame=frame[frame[key]==value]
    assert len(frame)==1,(kw,len(frame))
    return frame.iloc[0]
def f(x,d=4):return f'{float(x):.{d}f}'
def pc(x):return f'{100*float(x):.1f}%'
def table(frame,columns):
    return '\n'.join(['| '+' | '.join(title for key,title,fmt in columns)+' |','| '+' | '.join('---' for _ in columns)+' |']+['| '+' | '.join(fmt(row[key]) for key,title,fmt in columns)+' |' for _,row in frame.iterrows()])

def fields():
    decision=read('results/review-summaries/decision-context.csv');scale=read('results/review-summaries/effective-group-errors.csv')
    boot=read('results/review-summaries/landscape-resampling.csv');noise=read('results/review-label-error/comparisons.csv')
    ratios=read('results/review-summaries/preplanned-subsets.csv');budgets=read('results/review-summaries/all-budget-point-baselines.csv')
    p=one(decision,n=128,design='paired',subset='all');i=one(decision,n=128,design='independent',subset='all')
    dp=one(scale,label='reference-broad',design='paired',n=128);di=one(scale,label='reference-broad',design='independent',n=128)
    grass=one(ratios,n=128,subset='grassland_dominated');arable=one(ratios,n=128,subset='arable_dominated');allr=one(ratios,n=128,subset='all')
    br=one(boot,cohort='original',metric='mse_ratio');bp=one(boot,cohort='original',metric='paired_coverage');bi=one(boot,cohort='original',metric='independent_coverage')
    added=one(boot,cohort='additional_arable_broad',metric='mse_ratio');addedfine=one(boot,cohort='additional_arable_fine',metric='mse_ratio')
    z=one(noise,rate=0,coupling=0);e1=one(noise,rate=.01,coupling=0);e5=one(noise,rate=.05,coupling=0)
    lr=[one(scale,label='logistic-broad-'+rep,design='paired',n=128) for rep in ['tessera','alphaearth']]
    rf=[one(scale,label='forest-broad-'+rep,design='paired',n=128) for rep in ['tessera','alphaearth']]
    cases=read('results/tables/main/case-counts.csv').iloc[0]
    abstract=(f'Monitoring crop diversity for agricultural landscape management requires distinguishing annual changes from sampling error before reporting an increase or decrease. We benchmark revisited versus independent reference locations for Shannon diversity of Swiss declared crop groups in {int(cases.landscapes)} held-out landscapes and {int(cases.units)} adjacent-year contrasts, using 32–512 labels per year. '
      f'The preplanned direct-sampling comparison gave a revisited/independent mean squared error ratio of {f(allr.paired_independent_mse_ratio,3)} at 128 labels/year; prespecified grassland- and arable-dominated ratios were {f(grass.paired_independent_mse_ratio,3)} and {f(arable.paired_independent_mse_ratio,3)}. '
      f'Direct interval coverage was {pc(z.paired_coverage)} versus {pc(z.independent_coverage)}, and {pc(p.wrong_conditional)} versus {pc(i.wrong_conditional)} of reported directions were wrong. Predicting no change beat direct sampling at every tested budget and all frozen assisted estimates at 128 labels/year. Frozen logistic assistance from two annual satellite embedding products gave no RMSE gain with revisiting; frozen forests gave a modest one at that budget. '
      f'There were {int(cases.tiny_change)} contrasts with |ΔH|<0.01, {int(cases.zero_change)} exact zeros and {int(cases.labels_unchanged_all)} wholly unchanged label populations; none was excluded. '
      f'An exploratory translation to relative error in the effective-number ratio gives RMS errors of {f(dp.relative_effective_groups_rmse_percent,1)}% with revisiting, {f(di.relative_effective_groups_rmse_percent,1)}% independently and {f(dp.no_change_relative_rmse_percent,1)}% for no change at 128 labels/year. '
      'Further exploratory checks show that independent annual labelling errors remove most of the coverage deficit while worsening point error, and that the original assisted interval rule omitted a projection derivative, making intervals too wide. The headline gain and coverage deficit concern perfectly repeatable declaration labels on a fixed frame; field-audit errors, costs and ecological outcomes were not measured.')
    early=(f'For a reported direction at 128 labels/year, the observed wrong-direction share is {int(p.wrong_reports)}/{int(p.reports)} ({pc(p.wrong_conditional)}) with revisiting and {int(i.wrong_reports)}/{int(i.reports)} ({pc(i.wrong_conditional)}) independently. These conditional shares differ from wrong directions per trial. Across the {int(p.units)} landscape–transition units, revisited coverage has minimum {pc(p.coverage_min)}, 10th percentile {pc(p.coverage_p10)}, median {pc(p.coverage_median)} and 90th percentile {pc(p.coverage_p90)}; {int(p.coverage_below_0_90)} units are below 90%. This is substantial heterogeneity hidden by aggregate coverage. ')
    for subset,description in [('tiny','|ΔH|<0.01'),('non_tiny','|ΔH|≥0.01')]:
        a=one(decision,n=128,design='paired',subset=subset);b=one(decision,n=128,design='independent',subset=subset)
        early+=f'For {description}, wrong/report is {int(a.wrong_reports)}/{int(a.reports)} ({pc(a.wrong_conditional)}) revisited and {int(b.wrong_reports)}/{int(b.reports)} ({pc(b.wrong_conditional)}) independent. '
    dp512=one(scale,label='reference-broad',design='paired',n=512);p512=one(decision,n=512,design='paired',subset='all')
    exceptions=budgets[budgets.beats_no_change.astype(bool)].sort_values(['n','label','design'])
    early+=(f'\n\nDirect sampling at every tested budget remains worse than no change in aggregate: revisited RMSE at 512 is {f(dp512.rmse)} versus baseline {f(dp512.no_change_rmse)}. No change has lower squared error than the revisited direct MSE in {int(p.no_change_beats_unit_mse)}/{int(p.units)} units at 128 labels/year and {int(p512.no_change_beats_unit_mse)}/{int(p512.units)} at 512. This does not hold for every assisted estimator: ')
    early+='; '.join(f"{dict(forest_broad_frozen_alphaearth='RF + AlphaEarth',forest_broad_frozen_tessera='RF + TESSERA').get(r.label.replace('-','_'),r.label)}, {'revisited' if r.design=='paired' else r.design}, {int(r.n)} labels/year has RMSE {f(r.rmse)}" for _,r in exceptions.iterrows())+'. All original frozen methods and budgets are retained in results/review-summaries/all-budget-point-baselines.csv.'
    early+=(f'\n\nOn the effective-number scale, we evaluate the actual trial error 100[exp(estimated ΔH−true ΔH)−1], the percentage error in the estimated ratio of effective numbers of the specified groups. Its RMS is {f(dp.relative_effective_groups_rmse_percent,2)}% (direct revisited), {f(di.relative_effective_groups_rmse_percent,2)}% (independent) and {f(dp.no_change_relative_rmse_percent,2)}% (no change). These are newly added descriptive transformations, not exponentiated entropy RMSEs, species counts or measured ecological effects.')
    accuracy=(f'With revisiting, frozen logistic-assisted RMSE is {f(lr[0].rmse)}/{f(lr[1].rmse)} for TESSERA/AlphaEarth, compared with direct {f(dp.rmse)}. Frozen forests improve it to {f(rf[0].rmse)}/{f(rf[1].rmse)} at this budget. Thus the main direct precision gain uses no satellite input; frozen logistic assistance adds no point-accuracy benefit under revisiting in these conditions. Assistance can help with independent samples or other classifiers. Standard post-stratification by map class remains an untested comparator in this study; reviewer-only computations are not included as our results.')
    variability=(f'### 4.8. Exploratory review-response sensitivity\n\nThe prespecified n=128 grassland-dominated MSE ratio is {f(grass.paired_independent_mse_ratio,3)} across {int(grass.units)} contrasts; the arable-dominated ratio is {f(arable.paired_independent_mse_ratio,3)} across {int(arable.units)}. These subsets were fixed before results and differ from the later stable-arable support. Resampling whole landscapes after the review gives a 95% within-cohort percentile range {f(br.low,3)}–{f(br.high,3)} around the original ratio {f(br.estimate,3)}. Corresponding coverage ranges are {pc(bp.low)}–{pc(bp.high)} revisited and {pc(bi.low)}–{pc(bi.high)} independent. These are composition-sensitivity ranges on the convenience cohort, not national confidence intervals, and are wider than Monte Carlo precision on the fixed cohort.\n\n'
      f'For the additional stable-arable landscapes, the higher-replication broad ratio {f(added.estimate,3)} has range {f(added.low,3)}–{f(added.high,3)}; the fine ratio {f(addedfine.estimate,3)} has range {f(addedfine.low,3)}–{f(addedfine.high,3)}. Both include 1. The observed reversal and finer-scale gain are therefore not resolved against landscape-composition variation. The original point ratios are retained.\n\n'
      f'Table 8 perturbs sampled labels while keeping declaration-population truth fixed. With independent annual errors, coverage rises from {pc(z.paired_coverage)} to {pc(e1.paired_coverage)} at 1% error and {pc(e5.paired_coverage)} at 5%, while the MSE ratio rises from {f(z.mse_ratio,3)} to {f(e1.mse_ratio,3)} and {f(e5.mse_ratio,3)}. Absolute point accuracy worsens; this is not a benefit of error. Fully coupled uniforms largely retain the zero-error coverage deficit. Partly coupled scenarios lie between these particular endpoints, but this does not bound arbitrary real error processes. No tested error rate is an estimate of a real audit error rate.\n\n**Table 8. Post-review synthetic label-error scenarios, broad direct estimates at 128 labels/year. Annual coupling is a probability of shared random uniforms, not a fitted error correlation. All scenarios retained.**\n\n')
    variability+=table(noise,[('rate','Error probability',pc),('coupling','Annual coupling',lambda x:f(x,1)),('paired_rmse','Revisited RMSE',f),('independent_rmse','Independent RMSE',f),('mse_ratio','MSE ratio',lambda x:f(x,3)),('paired_coverage','Revisited coverage',pc),('independent_coverage','Independent coverage',pc)])
    long=read('results/review-summaries/long-contrast.csv');lp=one(long,n=512,design='paired')
    extra=(f'### E. Review-response decision summaries\n\nThe prespecified 2022→2025 contrast has its own no-change RMSE {f(lp.no_change_rmse)}, compared with direct revisited {f(one(long,n=128,design="paired").rmse)} at 128 and {f(lp.rmse)} at 512 labels/year. Thus the long contrast is assessed against its own signal scale, rather than importing the adjacent-year baseline.\n\n**Table E1. Prespecified longer contrast, newly tabulated after review.**\n\n')
    extra+=table(long,[('n','Labels/year',lambda x:str(int(x))),('design','Sample',str),('rmse','RMSE',f),('no_change_rmse','No-change RMSE',f),('coverage','Coverage',pc),('relative_effective_groups_rmse_percent','Relative effective-number RMS error (%)',lambda x:f(x,2))])
    methods=('After review, plan v15 fixes two exploratory analyses before execution. First, sampled labels at n=128 are independently replaced with probabilities 0, 0.01, 0.02 or 0.05 by a draw from that landscape-year’s class distribution excluding the true class. The target remains the error-free declaration-population change. Annual coupling probabilities 0, 0.5 and 1 share location/trial corruption uniforms across years, preserving each year’s marginal rule. Shared uniforms do not imply identical replacement categories when true labels or annual distributions differ. Saved draws, seeds, output arrays and noisy-label hashes permit offline reconstruction. The original interval and finite-population correction remain unchanged; they are not re-derived as a valid measurement-error variance. Second, 5,000 bootstrap resamples of whole landscapes preserve each landscape’s three contrasts. Percentile ranges describe within-cohort composition sensitivity only. Conditional error denominators, per-unit coverage distributions and actual transformed effective-number-ratio errors are also newly summarized from saved draws. All added analyses are exploratory; the original subset definitions and longer contrast were prespecified.')
    discussion=("The size of the revisiting gain and its coverage deficit depend on perfectly repeatable declaration labels. The same database supplies both benchmark truth and each sampled label; an unchanged location therefore always agrees across years. Independent field or photo-interpretation errors can remove many zero-standard-error samples while increasing point error, as the synthetic scenarios demonstrate. Persistent interpreter or parcel ambiguities can behave differently. Real audit error rates and their temporal dependence require measurement; they cannot be inferred from this benchmark.\n\n"
      "The original assisted interval rule omitted the derivative of the projection used to make estimated proportions valid. This produced overly wide intervals, rather than showing that model assistance inherently gives near-perfect coverage. The exploratory derivative-aware calculation substantially narrows them without changing a point estimate; its coverage is closer to independent direct sampling than to revisited direct sampling. It remains an approximate local calculation at changing category support.\n\n"
      "The direct precision gain is expected from established successive-occasion sampling theory, not a new sampling principle. Its practically relevant extent depends on support and landscape composition; the arable-dominated preplanned subset has a much smaller gain than the grassland-dominated one. Landscape-resampling ranges include this compositional variation, whereas Monte Carlo errors describe only simulation precision on fixed landscapes. Neither range licenses national extrapolation. Frozen logistic assistance did not improve revisited point accuracy; forests provided a modest gain at the illustrative budget and beat no change at the largest tested budget. A broad claim that no tested method beats no change would therefore be incorrect.\n\n"
      "A monitoring analyst should compare direct and assisted estimators with no change, report conditional wrong-direction shares alongside reporting frequency, and assess coverage on data matching the intended support and label process. Repeated and rotating panels remain candidate designs. These experiments do not establish field costs, an optimal rotation rate, or the effects of abstention on actual decisions.")
    return dict(REVISED_ABSTRACT=abstract,REVIEW_METHODS=methods,REVIEW_EARLY=early,REVIEW_ACCURACY=accuracy,REVIEW_RESULTS=variability,REVIEW_APPENDIX=extra,REVIEW_DISCUSSION=discussion,
      REVISION_HISTORY='## Revision history\n\nFollowing one review by an AI agent, the final version narrows the title and interpretation, adds synthetic independent/temporally coupled label-error scenarios and landscape resampling, foregrounds conditional wrong directions and model-assisted point accuracy, adds operational and classic prior-work context, and clarifies the omitted projection derivative. Original plans and results remain unchanged in submission-1; all added analyses and decisions are in protocol/plan-v15-review-response.md and review/response-1.md. The review and all reruns are not independent reproduction.')

def revise_claims(claims):
    by={r['claim_id']:r for r in claims};boot=read('results/review-summaries/landscape-resampling.csv');noise=read('results/review-label-error/comparisons.csv')
    for cid in ['C01','C02','C06']:
        by[cid]['scope']+=' Labels are error-free and perfectly repeatable readings of the declaration database; field/photo errors and their temporal dependence are not measured. See review/response-1.md R1-1.'
        by[cid]['reader_implication']+=' Assess label-error sensitivity before transferring this result to field or photo-interpreted audits.'
    by['C04']['text']='The original soft-logistic assisted interval rule, which omitted the projection derivative, gives overly conservative aggregate coverage and rarely reports directions.'
    by['C04']['reader_implication']='This behavior diagnoses the original interval rule, not a general advantage of model assistance; derivative-aware exploratory results are in C11 and review/response-1.md R1-5.'
    by['C10']['text']='The additional stable-arable cohort has an observed broad MSE ratio above 1 and fine ratio below 1; both landscape-resampling ranges include 1.'
    by['C10']['evidence_paths'].append('results/review-summaries/landscape-resampling.csv');by['C10']['experiment_ids'].append('E57-review-summaries')
    for tax in ['broad','fine']:
        r=one(boot,cohort='additional_arable_'+tax,metric='mse_ratio');by['C10']['expected'][tax+'_landscape_resampling_range']=[float(r.low),float(r.high)]
    by['C10']['scope']+=' Composition sensitivity is unresolved on six landscapes; neither a general reversal nor a fine-taxonomy advantage is established. Interpretation revised after R1-3, review/response-1.md.'
    def add(cid,text,path,expected,scope,implication,experiments):
        claims.append(dict(claim_id=cid,text=text,status='supported',evidence_paths=[path],source_ids=[],experiment_ids=experiments,scope=scope,
          verify=dict(command='python scripts/verify.py --all --output /ABSOLUTE/FRESH/OUTPUT',inspect=[path]),expected=expected,exploratory=True,reader_implication=implication))
    e=one(noise,rate=.01,coupling=0);e5=one(noise,rate=.05,coupling=0)
    add('C12','Synthetic independent annual label error reduces the revisited interval coverage deficit while worsening its point accuracy.',
      'results/review-label-error/comparisons.csv',dict(error_0_01_paired_coverage=float(e.paired_coverage),error_0_01_mse_ratio=float(e.mse_ratio),error_0_05_paired_coverage=float(e5.paired_coverage),error_0_05_mse_ratio=float(e5.mse_ratio)),
      'Exploratory post-review n=128 broad direct benchmark, fixed error-free target; specified replacement/coupling model, not estimated real error rates or a valid measurement-error interval.',
      'Both repeatability of audit labels and their temporal dependence matter when transferring panel results.', ['E56-review-label-error'])
    r=one(boot,cohort='original',metric='mse_ratio')
    add('C13','Landscape composition sensitivity is wider than Monte Carlo precision of the original fixed-cohort MSE ratio.',
      'results/review-summaries/landscape-resampling.csv',dict(n128_ratio=float(r.estimate),within_cohort_95_percentile_range=[float(r.low),float(r.high)]),
      'Exploratory 5,000 whole-landscape bootstrap resamples of 30 convenience-cohort landscapes, three original contrasts retained per landscape; not national uncertainty.',
      'Separate simulation precision from heterogeneity across landscapes.', ['E57-review-summaries'])
